code='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))

    def runs_on_edge(row):
        runs = []
        c = 0
        while c < w:
            color = grid[row][c]
            end = c + 1
            while end < w and grid[row][end] == color:
                end += 1
            if end - c >= 2 and color != background:
                runs.append((color, c, end - 1))
            c = end
        return runs

    candidates = []
    for r in (0, h - 1):
        candidates.extend((r, color, lo, hi) for color, lo, hi in runs_on_edge(r))
    pair = None
    for a in candidates:
        for b in candidates:
            if a[0] < b[0] and a[1] == b[1] and a[2] == b[2] and a[3] == b[3]:
                pair = (a, b)
                break
        if pair:
            break
    if pair is None:
        return out
    (r1, bar_color, lo1, hi1), (r2, _, lo2, hi2) = pair
    shift = lo2 - lo1
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != bar_color]
    for r, c, color in markers:
        if lo1 <= c <= hi1:
            out[r][c] = 4
            for rr in range(r1 + 1, r):
                out[rr][c] = color
            cc = c + shift
            if 0 <= cc < w:
                for rr in range(r1, r2):
                    out[rr][cc] = color
    return out
'''
